CREATE OR REPLACE FUNCTION public.claim_athlete_by_code(_code text, _surname text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _athlete uuid; BEGIN IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role IN ('athlete','parent')) THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT id INTO _athlete FROM public.athletes WHERE upper(athlete_code) = upper(trim(_code)) AND lower(surname) = lower(trim(_surname)) LIMIT 1; IF _athlete IS NULL THEN RETURN false; END IF; INSERT INTO public.athlete_guardians(user_id, athlete_id, relationship) VALUES (auth.uid(), _athlete, CASE WHEN EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'parent') THEN 'parent' ELSE 'self' END) ON CONFLICT DO NOTHING; RETURN true; END $$; REVOKE ALL ON FUNCTION public.claim_athlete_by_code(text,text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.claim_athlete_by_code(text,text) TO authenticated; CREATE UNIQUE INDEX IF NOT EXISTS athlete_guardians_user_athlete_unique ON public.athlete_guardians(user_id,athlete_id);
CREATE OR REPLACE FUNCTION public.join_school_by_code(_code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE _school uuid; BEGIN IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role IN ('school_admin','coach')) THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT id INTO _school FROM public.schools WHERE upper(school_code) = upper(trim(_code)) LIMIT 1; IF _school IS NULL THEN RETURN false; END IF; INSERT INTO public.school_users(user_id,school_id) VALUES (auth.uid(),_school) ON CONFLICT DO NOTHING; RETURN true; END $$; REVOKE ALL ON FUNCTION public.join_school_by_code(text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.join_school_by_code(text) TO authenticated; CREATE UNIQUE INDEX IF NOT EXISTS school_users_user_school_unique ON public.school_users(user_id,school_id);
CREATE TABLE public.consent_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), athlete_id uuid NOT NULL REFERENCES public.athletes(id) ON DELETE CASCADE, requester_name text NOT NULL, requester_email text NOT NULL, status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','sent','completed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT, UPDATE ON public.consent_requests TO authenticated; GRANT ALL ON public.consent_requests TO service_role; ALTER TABLE public.consent_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "staff manage consent requests" ON public.consent_requests FOR ALL TO authenticated USING (public.is_vito_staff(auth.uid())) WITH CHECK (public.is_vito_staff(auth.uid())); CREATE TRIGGER consent_requests_updated BEFORE UPDATE ON public.consent_requests FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();